from pysat.solvers import Glucose3
from pysat.formula import CNF

# Variables: x[i][h] means pigeon i goes to hole h
# We'll encode: each pigeon in exactly one hole, each hole at most one pigeon

n_pigeons = 4
n_holes = 3

# Variable mapping: (i, h) -> var number
def var(i, h):
    return i * n_holes + h + 1

cnf = CNF()

# Each pigeon in at least one hole
for i in range(n_pigeons):
    cnf.add_clause([var(i, h) for h in range(n_holes)])

# Each pigeon in at most one hole (pairwise mutual exclusion)
for i in range(n_pigeons):
    for h1 in range(n_holes):
        for h2 in range(h1+1, n_holes):
            cnf.add_clause([-var(i, h1), -var(i, h2)])

# Each hole at most one pigeon
for h in range(n_holes):
    for i1 in range(n_pigeons):
        for i2 in range(i1+1, n_pigeons):
            cnf.add_clause([-var(i1, h), -var(i2, h)])

solver = Glucose3(cnf)
result = solver.solve()
print("Satisfiable:", result)

